window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9f83f23b69f169e5"]={"versions": [{"id": "FIG-9f83f23b69f169e5", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des segmentierten 1:1-Transportprotokoll-Ablaufs im AUTOSAR FlexRay Transport Protocol (FrTp). Das Diagramm veranschaulicht das Flusssteuerungs- und Wiederholungsverfahren (Retry Mechanism) bei fehlerhafter bzw. verloren gegangener Segmentübertragung unter Verwendung von Flow-Control- und Acknowledge-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Sender</strong>: Sendende FrTp-Protokollinstanz.</li>\n<li><strong>Receiver</strong>: Empfangende FrTp-Protokollinstanz.</li>\n<li><strong>N-PDUs / Frame-Typen</strong>:</li>\n<li><code>FF</code>: First Frame zur Initiierung der segmentierten Übertragung.</li>\n<li><code>FC (Clear To Send)</code>: Flow Control Frame zur Freigabe der weiteren Segmentübertragung.</li>\n<li><code>CF #x</code>: Consecutive Frame mit Sequenznummer <code>#x</code> (<code>CF #0</code> bis <code>CF #3</code>).</li>\n<li><code>CF2 #x</code>: Consecutive Frame des Folgeblocks bzw. zweiten Übertragungsabschnitts mit Sequenznummer <code>#x</code> (<code>CF2 #4</code> bis <code>CF2 #7</code>).</li>\n<li><code>AF (Negative Acknowledge, #1)</code>: Acknowledge Frame mit negativem Quittungsstatus und Angabe der ersten fehlerhaften Sequenznummer (<code>#1</code>).</li>\n<li><code>AF (Positive Acknowledge)</code>: Acknowledge Frame mit positiver Bestätigung des erfolgreich empfangenen Datenblocks.</li>\n<li><strong>Konfigurationsparameter</strong>:</li>\n<li><code>FrTp_BS = 4</code>: Block Size Parameter, legt die Übertragungsblockgröße auf 4 Consecutive Frames fest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freigabe</strong>: Der Sender übermittelt einen First Frame (<code>FF</code>) an den Receiver. Der Receiver antwortet mit <code>FC (Clear To Send)</code>.</li>\n<li><strong>Erster Block & Fehlerfall</strong>: Der Sender beginnt mit der Aussendung des ersten Blocks (<code>FrTp_BS = 4</code>), bestehend aus <code>CF #0</code>, <code>CF #1</code>, <code>CF #2</code> und <code>CF #3</code>. Das Segment <code>CF #1</code> wird gestört oder geht verloren (<code>faulty or missing</code>).</li>\n<li><strong>Negative Quittierung</strong>: Nach Eintreffen von <code>CF #3</code> sendet der Receiver einen <code>AF (Negative Acknowledge, #1)</code>, der die Sequenznummer des ersten fehlerhaften Frames referenziert.</li>\n<li><strong>Wiederholung (Retry)</strong>: Der Sender setzt die Übertragung ab der fehlerhaften Sequenznummer erneut auf und überträgt alle verbleibenden Frames des Blocks erneut (<code>CF #1</code>, <code>CF #2</code>, <code>CF #3</code>).</li>\n<li><strong>Nächste Blockfreigabe</strong>: Der Receiver quittiert den vollständigen Empfang des ersten Blocks mit einem weiteren <code>FC (Clear To Send)</code>.</li>\n<li><strong>Folgeblock & Abschluss</strong>: Der Sender übermittelt den nachfolgenden Block mit <code>CF2 #4</code>, <code>CF2 #5</code>, <code>CF2 #6</code> und <code>CF2 #7</code>. Nach vollständigem und fehlerfreiem Empfang bestätigt der Receiver mit <code>AF (Positive Acknowledge)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Bei Empfang eines negativen Acknowledgements muss der Sender die Übertragung ab der im Acknowledge übermittelten Sequenznummer bis zum Ende des aktuellen Blocks wiederholen (Selective-Go-Back-Verhalten).</li>\n<li>Zur Vermeidung unendlicher Wiederholungsschleifen bei permanenten Übertragungsfehlern ist die maximale Anzahl an Retry-Versuchen über entsprechende FrTp-Konfigurationsparameter zu begrenzen.</li>\n<li>Die Blockgröße <code>FrTp_BS</code> definiert verbindlich das Quittierungs- und Flow-Control-Intervall für Consecutive Frames.</li>\n<li>Software-Implementierungen des FrTp müssen Empfangspuffer und Sequenzüberwachungslogik so dimensionieren, dass Out-of-Sequence-Frames erkannt und die Sequenznummer des ersten fehlerhaften Frames im AF gemeldet werden.</li>\n</ul>"}, {"id": "FIG-e6143e8716863cae", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des segmentierten 1:1-Transportprotokoll-Ablaufs im AUTOSAR FlexRay Transport Protocol (FrTp). Das Diagramm veranschaulicht das Flusssteuerungs- und Wiederholungsverfahren (Retry Mechanism) bei fehlerhafter bzw. verloren gegangener Segmentübertragung unter Verwendung von Flow-Control- und Acknowledge-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Sender</strong>: Sendende FrTp-Protokollinstanz.</li>\n<li><strong>Receiver</strong>: Empfangende FrTp-Protokollinstanz.</li>\n<li><strong>N-PDUs / Frame-Typen</strong>:</li>\n<li><code>FF</code>: First Frame zur Initiierung der segmentierten Übertragung.</li>\n<li><code>FC (Clear To Send)</code>: Flow Control Frame zur Freigabe der weiteren Segmentübertragung.</li>\n<li><code>CF #x</code>: Consecutive Frame mit Sequenznummer <code>#x</code> (<code>CF #0</code> bis <code>CF #3</code>).</li>\n<li><code>CF2 #x</code>: Consecutive Frame des Folgeblocks bzw. zweiten Übertragungsabschnitts mit Sequenznummer <code>#x</code> (<code>CF2 #4</code> bis <code>CF2 #7</code>).</li>\n<li><code>AF (Negative Acknowledge, #1)</code>: Acknowledge Frame mit negativem Quittungsstatus und Angabe der ersten fehlerhaften Sequenznummer (<code>#1</code>).</li>\n<li><code>AF (Positive Acknowledge)</code>: Acknowledge Frame mit positiver Bestätigung des erfolgreich empfangenen Datenblocks.</li>\n<li><strong>Konfigurationsparameter</strong>:</li>\n<li><code>FrTp_BS = 4</code>: Block Size Parameter, legt die Übertragungsblockgröße auf 4 Consecutive Frames fest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Freigabe</strong>: Der Sender übermittelt einen First Frame (<code>FF</code>) an den Receiver. Der Receiver antwortet mit <code>FC (Clear To Send)</code>.</li>\n<li><strong>Erster Block & Fehlerfall</strong>: Der Sender beginnt mit der Aussendung des ersten Blocks (<code>FrTp_BS = 4</code>), bestehend aus <code>CF #0</code>, <code>CF #1</code>, <code>CF #2</code> und <code>CF #3</code>. Das Segment <code>CF #1</code> wird gestört oder geht verloren (<code>faulty or missing</code>).</li>\n<li><strong>Negative Quittierung</strong>: Nach Eintreffen von <code>CF #3</code> sendet der Receiver einen <code>AF (Negative Acknowledge, #1)</code>, der die Sequenznummer des ersten fehlerhaften Frames referenziert.</li>\n<li><strong>Wiederholung (Retry)</strong>: Der Sender setzt die Übertragung ab der fehlerhaften Sequenznummer erneut auf und überträgt alle verbleibenden Frames des Blocks erneut (<code>CF #1</code>, <code>CF #2</code>, <code>CF #3</code>).</li>\n<li><strong>Nächste Blockfreigabe</strong>: Der Receiver quittiert den vollständigen Empfang des ersten Blocks mit einem weiteren <code>FC (Clear To Send)</code>.</li>\n<li><strong>Folgeblock & Abschluss</strong>: Der Sender übermittelt den nachfolgenden Block mit <code>CF2 #4</code>, <code>CF2 #5</code>, <code>CF2 #6</code> und <code>CF2 #7</code>. Nach vollständigem und fehlerfreiem Empfang bestätigt der Receiver mit <code>AF (Positive Acknowledge)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Bei Empfang eines negativen Acknowledgements muss der Sender die Übertragung ab der im Acknowledge übermittelten Sequenznummer bis zum Ende des aktuellen Blocks wiederholen (Selective-Go-Back-Verhalten).</li>\n<li>Zur Vermeidung unendlicher Wiederholungsschleifen bei permanenten Übertragungsfehlern ist die maximale Anzahl an Retry-Versuchen über entsprechende FrTp-Konfigurationsparameter zu begrenzen.</li>\n<li>Die Blockgröße <code>FrTp_BS</code> definiert verbindlich das Quittierungs- und Flow-Control-Intervall für Consecutive Frames.</li>\n<li>Software-Implementierungen des FrTp müssen Empfangspuffer und Sequenzüberwachungslogik so dimensionieren, dass Out-of-Sequence-Frames erkannt und die Sequenznummer des ersten fehlerhaften Frames im AF gemeldet werden.</li>\n</ul>"}], "trans": [{"from": "FIG-9f83f23b69f169e5", "to": "FIG-e6143e8716863cae", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
